#!/usr/bin/env python3
"""Derive init-script templates from observed behaviour of the reference binary.

Development-time tool: probes ./executable's `init` output across the full
cross-product of the flags/env vars that affect it, then computes a base
template plus per-hole fragment tables.  The result is verified to reproduce
every observed combination byte-for-byte.
"""
import difflib
import itertools
import os
import subprocess
import sys

EXE = "/workspace/executable"
SHELLS = ["bash", "elvish", "fish", "nushell", "posix", "powershell", "tcsh", "xonsh", "zsh"]
HOOKS = ["none", "prompt", "pwd"]
SENT = "qzsentinelq"

DIMS = ["hook", "cmd", "echo", "resolve"]


def run(shell, hook, cmd, echo, resolve):
    env = dict(os.environ)
    env.pop("_ZO_ECHO", None)
    env.pop("_ZO_RESOLVE_SYMLINKS", None)
    if echo:
        env["_ZO_ECHO"] = "1"
    if resolve:
        env["_ZO_RESOLVE_SYMLINKS"] = "1"
    args = [EXE, "init", shell, "--hook", hook]
    if cmd is None:
        args.append("--no-cmd")
    else:
        args += ["--cmd", cmd]
    out = subprocess.run(args, env=env, capture_output=True, check=True)
    assert out.stderr == b"", out.stderr
    return out.stdout.decode()


def combos():
    for hook, cmd, echo, resolve in itertools.product(
        HOOKS, [SENT, None], [False, True], [False, True]
    ):
        yield {"hook": hook, "cmd": cmd, "echo": echo, "resolve": resolve}


def align(base, var):
    """Map base line index -> var line index for lines inside equal blocks."""
    m = {}
    sm = difflib.SequenceMatcher(a=base, b=var, autojunk=False)
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == "equal":
            for k in range(i2 - i1):
                m[i1 + k] = j1 + k
    return m, sm.get_opcodes()


def changed_ranges(base, var):
    _, ops = align(base, var)
    out = []
    for tag, i1, i2, _j1, _j2 in ops:
        if tag != "equal":
            out.append((i1, i2))
    return out


def merge(ranges, nlines):
    """Merge overlapping/adjacent ranges into disjoint holes."""
    if not ranges:
        return []
    # An insertion at position p (i1==i2==p) should merge with a hole touching p.
    rs = sorted(ranges)
    merged = [list(rs[0])]
    for a, b in rs[1:]:
        if a <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    return [tuple(x) for x in merged]


def extract(shell):
    base_state = {"hook": "pwd", "cmd": SENT, "echo": False, "resolve": False}
    base_txt = run(shell, **base_state)
    base = base_txt.splitlines(keepends=True)

    outs = {}
    for st in combos():
        key = (st["hook"], st["cmd"] is None, st["echo"], st["resolve"])
        outs[key] = run(shell, **st)

    allr = []
    for txt in outs.values():
        allr += changed_ranges(base, txt.splitlines(keepends=True))
    holes = merge(allr, len(base))

    # For each hole, per combo, extract the corresponding variant text.
    hole_texts = {i: {} for i in range(len(holes))}
    for key, txt in outs.items():
        var = txt.splitlines(keepends=True)
        m, _ = align(base, var)
        for i, (a, b) in enumerate(holes):
            lo = 0 if a == 0 else m[a - 1] + 1
            hi = m[b] if b < len(base) else len(var)
            hole_texts[i][key] = "".join(var[lo:hi])

    # Which dims does each hole depend on?
    deps = {}
    for i in range(len(holes)):
        d = []
        for dim_i, dim in enumerate(DIMS):
            # vary this dim while holding others; does the text change?
            varies = False
            for key in hole_texts[i]:
                for alt in set(k[dim_i] for k in hole_texts[i]):
                    k2 = list(key)
                    k2[dim_i] = alt
                    k2 = tuple(k2)
                    if k2 in hole_texts[i] and hole_texts[i][k2] != hole_texts[i][key]:
                        varies = True
            if varies:
                d.append(dim)
        deps[i] = d
    return base, holes, hole_texts, deps, outs


def main():
    for shell in SHELLS:
        base, holes, hole_texts, deps, outs = extract(shell)
        print(f"===== {shell}: {len(base)} lines, {len(holes)} holes")
        for i, (a, b) in enumerate(holes):
            keys = sorted(set(
                tuple(k[DIMS.index(d)] for d in deps[i]) for k in hole_texts[i]
            ))
            nvar = len(set(hole_texts[i].values()))
            print(f"  hole {i}: base lines {a+1}..{b} deps={deps[i]} variants={nvar}")
        # verify reconstruction
        bad = 0
        for key, txt in outs.items():
            parts = []
            prev = 0
            for i, (a, b) in enumerate(holes):
                parts.append("".join(base[prev:a]))
                parts.append(hole_texts[i][key])
                prev = b
            parts.append("".join(base[prev:]))
            if "".join(parts) != txt:
                bad += 1
        print(f"  reconstruction: {len(outs)-bad}/{len(outs)} ok")


if __name__ == "__main__":
    main()

