#!/usr/bin/env python3
"""Emit directive-annotated init templates from observed binary behaviour.

Writes one .tpl per shell into the given output directory, then verifies that
rendering every flag/env combination reproduces the observed output byte-exactly.
"""
import importlib.util
import itertools
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "extract.py")).read()
src = src.replace('if __name__ == "__main__":\n    dump()', "")
ex = type(sys)("ex")
exec(compile(src, "extract.py", "exec"), ex.__dict__)

DIMS = ex.DIMS
SENT = ex.SENT
OUT = sys.argv[1]

# dim -> ordered list of (condition-text, key-value); None condition == %else
COND = {
    "hook": [("hook none", "none"), ("hook prompt", "prompt"), (None, "pwd")],
    "cmd": [("cmd", False), (None, True)],
    "echo": [("echo", True), (None, False)],
    "resolve": [("resolve", True), (None, False)],
}


def emit(deps, texts, prefix=()):
    """Render a nested %if/%elif/%else/%end block for one hole."""
    if not deps:
        body = texts[prefix]
        return body
    dim, rest = deps[0], deps[1:]
    branches = []
    for cond, val in COND[dim]:
        branches.append((cond, emit(rest, texts, prefix + (val,))))
    # Collapse when every branch is identical.
    if len(set(b for _, b in branches)) == 1:
        return branches[0][1]
    out = []
    first = True
    for cond, body in branches:
        if cond is None:
            if body == "":
                continue
            out.append("%else\n" if not first else "")
            if first:
                raise AssertionError("first branch cannot be %else")
        else:
            out.append(("%if " if first else "%elif ") + cond + "\n")
